const validTypes = [
  'discovery_interview',
  'usability_test',
  'concept_test',
  'card_sort',
  'survey',
  'diary_study',
  'field_study',
  'other'
];

const input = $input.item.json;

const projectName = (input.projectName || '').toString().trim();
if (!projectName) {
  throw new Error('projectName is required and cannot be empty');
}

let projectType = (input.projectType || '').toString().trim();
if (!validTypes.includes(projectType)) {
  projectType = 'discovery_interview';
}

const researchGoal = (input.researchGoal || '').toString().trim();
const targetAudience = (input.targetAudience || '').toString().trim();
const additionalContext = (input.additionalContext || '').toString().trim();

return {
  projectName,
  projectType,
  researchGoal,
  targetAudience,
  additionalContext
};

