const project = $('create_project').item.json;
const folder = $('create_folder').item.json;
const validated = $('validate').item.json;

const projectId = project.id;

// Validate UUID format — fail loudly if we somehow get a numeric or non-UUID id
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!projectId || !uuidRegex.test(projectId)) {
  throw new Error(`create_project returned a non-UUID project ID: "${projectId}". Expected a UUID from the project table.`);
}

const projectName = validated.projectName;
const projectType = validated.projectType;
const folderId = folder.id;

const googleDriveUrl = 'https://drive.google.com/drive/folders/' + folderId;
const pidgeonheadUrl = 'https://pidgeonhead.netlify.app/projects/' + projectId;

const message = 'Created project "' + projectName + '" (' + projectType + ').\n' +
  'PidgeonHead: ' + pidgeonheadUrl + '\n' +
  'Google Drive folder: ' + googleDriveUrl;

return {
  projectId,
  projectName,
  projectType,
  googleDriveUrl,
  pidgeonheadUrl,
  message
};
